  function quantity(id){return Number(state.cart[id]||0)}
  function cartCount(){return Object.keys(state.cart).reduce(function(sum,id){return sum+quantity(id)},0)}
  function subtotal(){return Object.keys(state.cart).reduce(function(sum,id){var item=products.find(function(p){return p.id===id});return sum+(item?item.price*quantity(id):0)},0)}
  function fulfillment(){var el=document.querySelector('input[name="fulfillment"]:checked');return el?el.value:'delivery'}
  function deliveryCost(){return fulfillment()==='pickup'||subtotal()>=990||subtotal()===0?0:200}
  function productById(id){return products.find(function(p){return p.id===id})}
  function renderCategories(){els.categories.innerHTML=categories.map(function(cat){return '<button type="button" class="category-pill'+(cat===state.category?' active':'')+'" data-category="'+escapeHtml(cat)+'">'+escapeHtml(cat)+'</button>'}).join('')}
