  function renderCart(){var lines=Object.keys(state.cart).map(function(id){var p=productById(id);if(!p||!quantity(id))return '';return '<div class="cart-row"><div><h3>'+escapeHtml(p.name)+'</h3><small>'+money(p.price)+' · '+escapeHtml(p.weight)+'</small></div><div class="quantity-control"><button type="button" data-step="-1" data-id="'+p.id+'" aria-label="Уменьшить">−</button><span>'+quantity(id)+'</span><button type="button" data-step="1" data-id="'+p.id+'" aria-label="Добавить">+</button></div><strong class="row-price">'+money(p.price*quantity(id))+'</strong></div>'}).join('');document.getElementById('cartItems').innerHTML=lines||'<div class="empty-state">Корзина пока пуста</div>';var sub=subtotal(),ship=sub>=990?0:200;updatePersonOptions(sub);document.getElementById('subtotal').textContent=money(sub);document.getElementById('deliveryCost').textContent=fulfillment()==='pickup'||sub===0?'0 ₽':(ship===0?'Бесплатно':money(ship));document.getElementById('grandTotal').textContent=money(sub+deliveryCost());document.getElementById('checkoutTotal').textContent=money(sub+deliveryCost());document.getElementById('shippingNote').textContent=fulfillment()==='pickup'?'Самовывоз: ул. Некрасова, 59. Минимальной суммы заказа нет.':sub>=990?'Доставка бесплатная — корзина от 990 ₽.':'Добавьте ещё на '+money(990-sub)+' для бесплатной доставки. Доставка сейчас — 200 ₽.';document.getElementById('toCheckout').disabled=sub===0;}
